def execute(arguments):
    """
    生成哈希值

    参数:
        arguments (dict): 包含以下字段
            - text (str): 要哈希的文本，与 file_path 二选一
            - file_path (str): 文件路径，与 text 二选一
            - algorithm (str): 哈希算法，"md5"、"sha1"、"sha256"（默认）、"sha512"
            - encoding (str): 文本编码，默认 "utf-8"

    返回:
        dict: 包含哈希结果的字典
            - success (bool): 是否成功
            - hash (str): 哈希值
            - algorithm (str): 使用的算法
            - input_type (str): 输入类型 "text" 或 "file"
            - input (str): 输入内容（文本或文件路径）
            - error (str): 错误信息（失败时）
    """
    import hashlib
    import os

    text = arguments.get("text", "")
    file_path = arguments.get("file_path", "")
    algorithm = arguments.get("algorithm", "sha256").lower()
    encoding = arguments.get("encoding", "utf-8")

    if not text and not file_path:
        return {"success": False, "error": "请提供文本或文件路径"}

    algorithms = {
        "md5": hashlib.md5,
        "sha1": hashlib.sha1,
        "sha256": hashlib.sha256,
        "sha512": hashlib.sha512
    }

    if algorithm not in algorithms:
        return {"success": False, "error": f"不支持的算法: {algorithm}，支持: {list(algorithms.keys())}"}

    try:
        hasher = algorithms[algorithm]()

        if file_path:
            if not os.path.exists(file_path):
                return {"success": False, "error": f"文件不存在: {file_path}"}

            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    hasher.update(chunk)

            return {
                "success": True,
                "hash": hasher.hexdigest(),
                "algorithm": algorithm,
                "input_type": "file",
                "input": file_path
            }
        else:
            hasher.update(text.encode(encoding))
            return {
                "success": True,
                "hash": hasher.hexdigest(),
                "algorithm": algorithm,
                "input_type": "text",
                "input": text[:100] + "..." if len(text) > 100 else text
            }
    except Exception as e:
        return {"success": False, "error": f"哈希生成失败: {str(e)}"}
